//! Unique original constructor-name closure and shadow judgment; header/body DATA only.
use std::collections::{HashMap,HashSet};
use crate::{dm::dx::{lineage,Proc},tree::SourceFile,key_policy_control::Control,pat};
#[cfg(feature="legacy-sem")]use crate::{dm::dx::DxIndex,tree::Tree};
pub(crate) const PRESET_FILES:&str="code/library/capabilities/preset";
pub(crate) const CAPS_DIR:&str="code/library/capabilities/";
pub struct ProcFact{pub relative:String,pub owner:String,pub name:String,pub line:usize,body:Option<String>}
pub struct Context{reserved:HashSet<String>,engine:HashSet<String>,cap_types:HashSet<String>}
fn set_add<C:Control>(set:&mut HashSet<String>,value:&str,c:&mut C)->Result<(),C::Error>{c.checkpoint()?;if set.contains(value){return Ok(())}if C::CHECKED&&set.len()==set.capacity(){let target=set.capacity().checked_mul(2).map(|n|n.max(4)).ok_or_else(||c.overflow())?;let bound=target.checked_mul(4).ok_or_else(||c.overflow())?;crate::key_policy_control::reserve(c,||bound.checked_mul(std::mem::size_of::<String>())?.checked_add(4096))?;set.try_reserve(target-set.len()).map_err(|_|c.allocation_failed())?;if set.capacity()>bound{return Err(c.allocation_failed())}}set.insert(crate::raw_tree_report::own(c,value)?);Ok(())}
pub fn cap_type<C:Control>(name:&str,args:&[String],c:&mut C)->Result<Option<String>,C::Error>{c.checkpoint()?;match name{"CAPABILITY_TYPE"=>args.get(2).map(|v|crate::raw_tree_report::own(c,v.trim())).transpose(),"CAPABILITY_DEF"=>args.first().map(|v|crate::key_policy_control::format(c,format_args!("/datum/capability/def/{}",v.trim()))).transpose(),_=>Ok(None)}}
fn fact<C:Control>(proc:&Proc,body:Option<String>,c:&mut C)->Result<ProcFact,C::Error>{c.checkpoint()?;Ok(ProcFact{relative:crate::raw_tree_report::own(c,&proc.rel)?,owner:crate::raw_tree_report::own(c,&proc.path)?,name:crate::raw_tree_report::own(c,&proc.name)?,line:proc.line,body})}
fn needs_body(proc:&Proc)->bool{proc.is_global()&&(proc.name.starts_with("cap_")||proc.rel.starts_with(CAPS_DIR))}
pub fn file_facts<C:Control,T:Control<Error=C::Error>>(file:&SourceFile,keep:&mut C,temp:&mut T)->Result<Vec<ProcFact>,C::Error>{keep.checkpoint()?;crate::key_policy_control::reserve(temp,||file.text().len().checked_mul(file.rel.len().checked_mul(4)?.checked_add(512)?)?.checked_add(4096))?;let clean=file.clean();let mut out=Vec::new();for proc in crate::dm::dx::procs_in(file){keep.checkpoint()?;let body=if needs_body(&proc){let mut width=0usize;for k in 0..proc.body_len{keep.checkpoint()?;width=width.checked_add(clean.line(proc.body_start+k).len()).and_then(|n|n.checked_add(1)).ok_or_else(||keep.overflow())?;}crate::key_policy_control::reserve(keep,||width.checked_mul(4)?.checked_add(128))?;let mut body=String::new();body.try_reserve_exact(width).map_err(|_|keep.allocation_failed())?;if C::CHECKED&&body.capacity()>width.saturating_mul(4).saturating_add(128){return Err(keep.allocation_failed())}for k in 0..proc.body_len{keep.checkpoint()?;if k!=0{body.push('\n');}body.push_str(clean.line(proc.body_start+k));}Some(body)}else{None};crate::raw_tree_report::row(keep,&mut out)?;out.push(fact(&proc,body,keep)?);}keep.checkpoint()?;Ok(out)}
pub fn context<'a,C:Control>(rows:impl IntoIterator<Item=&'a ProcFact>,caps:impl IntoIterator<Item=&'a String>,c:&mut C)->Result<Context,C::Error>{let mut reserved=HashSet::new();let mut engine=HashSet::new();let mut cap_types=HashSet::new();let mut candidates:HashMap<String,&str>=HashMap::new();for proc in rows{c.checkpoint()?;if proc.owner!="/"{continue}if proc.relative.starts_with("code/engine/"){set_add(&mut engine,&proc.name,c)?;}if proc.name.starts_with("cap_")||proc.relative.starts_with(PRESET_FILES){set_add(&mut reserved,&proc.name,c)?;}if proc.name.starts_with("cap_")||proc.relative.starts_with(CAPS_DIR){if C::CHECKED&&candidates.len()==candidates.capacity()&&!candidates.contains_key(&proc.name){let target=candidates.capacity().checked_mul(2).map(|n|n.max(4)).ok_or_else(||c.overflow())?;let bound=target.checked_mul(4).ok_or_else(||c.overflow())?;crate::key_policy_control::reserve(c,||bound.checked_mul(std::mem::size_of::<(String,&str)>())?.checked_add(4096))?;candidates.try_reserve(target-candidates.len()).map_err(|_|c.allocation_failed())?;if candidates.capacity()>bound{return Err(c.allocation_failed())}}candidates.insert(crate::raw_tree_report::own(c,&proc.name)?,proc.body.as_deref().unwrap_or(""));}}
 let new_cap=pat!(r"\bnew\s+/datum/capability\b|\bvar/datum/capability[\w/]*\s*=\s*new\b");let call=pat!(r"(?<![\w./:])([A-Za-z_]\w*)\s*\(");let mut builders=HashSet::new();for(name,body)in &candidates{c.checkpoint()?;if new_cap.is_match(body){set_add(&mut builders,name,c)?;}}let mut grew=true;while grew{c.checkpoint()?;grew=false;for(name,body)in &candidates{c.checkpoint()?;if builders.contains(name){continue}let mut hit=false;for m in call.captures_iter(body){c.checkpoint()?;if builders.contains(m.s(1)){hit=true;break}}if hit{set_add(&mut builders,name,c)?;grew=true;}}}for name in builders{set_add(&mut reserved,&name,c)?;}for name in caps{set_add(&mut cap_types,name,c)?;}c.checkpoint()?;Ok(Context{reserved,engine,cap_types})}
pub fn judge<'a,C:Control>(rows:impl IntoIterator<Item=&'a ProcFact>,context:&Context,c:&mut C)->Result<(Vec<(&'static str,usize)>,Vec<(&'static str,usize)>),C::Error>{let mut atoms=Vec::new();let mut parts=Vec::new();let mut peak=0usize;for proc in rows{c.checkpoint()?;if proc.owner=="/"{continue}crate::raw_tree_report::peak(c,&mut peak,||proc.owner.len().checked_mul(proc.owner.len())?.checked_mul(8)?.checked_add(4096))?;let chain=lineage(&proc.owner);if context.reserved.contains(&proc.name)&&chain.iter().any(|p|p=="/atom"){crate::raw_tree_report::row(c,&mut atoms)?;atoms.push(("dx_constructor_shadow",proc.line));}if context.engine.contains(&proc.name)&&(context.cap_types.contains(&proc.owner)||chain.iter().any(|p|context.cap_types.contains(p))){crate::raw_tree_report::row(c,&mut parts)?;parts.push(("part_constructor_shadow",proc.line));}}c.checkpoint()?;Ok((atoms,parts))}
#[cfg(feature="legacy-sem")]
fn legacy_facts(tree:&Tree,procs:&[Proc])->Vec<ProcFact>{procs.iter().map(|p|{let body=needs_body(p).then(||p.body(tree).join("\n"));fact(p,body,&mut crate::key_policy_control::Compatibility).expect("original constructor facts")}).collect()}
#[cfg(feature="legacy-sem")]
fn legacy_caps(tree:&Tree)->Vec<String>{let decls=crate::sem::decls::Decls::get(tree);let mut out=Vec::new();for name in ["CAPABILITY_TYPE","CAPABILITY_DEF"]{for marker in decls.markers_named(name){if let Some(name)=cap_type(name,&marker.args,&mut crate::key_policy_control::Compatibility).expect("original constructor marker"){out.push(name);}}}out}
#[cfg(feature="legacy-sem")]
pub(crate) fn scan_procs(tree:&Tree,procs:&[Proc])->Vec<(&'static str,String,usize)>{let facts=legacy_facts(tree,procs);let caps=Vec::new();let context=context(&facts,&caps,&mut crate::key_policy_control::Compatibility).expect("original constructor names");let mut out=Vec::new();for fact in &facts{let(rows,_)=judge([fact],&context,&mut crate::key_policy_control::Compatibility).expect("original atom shadows");out.extend(rows.into_iter().map(|(r,n)|(r,fact.relative.clone(),n)));}out}
#[cfg(feature="legacy-sem")]
pub(crate) fn scan_part_shadows(tree:&Tree,procs:&[Proc])->Vec<(&'static str,String,usize)>{let facts=legacy_facts(tree,procs);let caps=legacy_caps(tree);let context=context(&facts,&caps,&mut crate::key_policy_control::Compatibility).expect("original part constructors");let mut out=Vec::new();for fact in &facts{let(_,rows)=judge([fact],&context,&mut crate::key_policy_control::Compatibility).expect("original part shadows");out.extend(rows.into_iter().map(|(r,n)|(r,fact.relative.clone(),n)));}out}
#[cfg(feature="legacy-sem")]
pub fn scan(tree:&Tree,files:&[&SourceFile])->Vec<(&'static str,String,usize)>{let idx=DxIndex::get(tree,files);let mut found=scan_procs(tree,&idx.procs);found.extend(scan_part_shadows(tree,&idx.procs));found}
